// 先核真实来源，再核重放/冲突/重复绑定/失败候选及返泊释放，不额外花时间或转钱货。
int main(){try{WorldFixture f;f.common.state().next_instance_id=4;f.access.fact_exists=[&](const StableId& id){return f.common.state().facts.find(id)!=nullptr;};for(const auto& v:f.state.vessels){f.catalog.vessels.push_back({v.id,v.hull_id,v.cargo_inventory_id,v.berth_id,v.owner,v.integrity});}NavalForm form{"embark-one",f.request};for(auto& v:f.state.vessels)v.origin_source="author:"+v.id;auto before=take(render_boundary_json(encode_common_state(f.common.state())));auto q=take(preview_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",form));check(!q.replayed&&q.formation.has_value(),"actual berth formation receives finite load quote");auto result=take(apply_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",form));check(result.kind=="naval_form"&&result.fleet_id=="fleet:4"&&result.receipt_id=="naval_action:5"&&f.common.tick()==4,"formation allocates original global identities without time or movement");check(f.common.state().facts.find(result.receipt_id)&&f.common.state().facts.find(result.receipt_id)->domain=="military_naval","single source fact registered in Common");check(validate_naval_world(f.common,f.military,f.mc,f.access,f.state,f.catalog).ok,"created fleet references original source facts and authored assets");auto forged=f.state;forged.fleets[0].appointment_source="missing";check(!validate_naval_world(f.common,f.military,f.mc,f.access,forged,f.catalog).ok,"cold forged appointment source rejects");forged=f.state;forged.vessels[0].integrity=79;check(!validate_naval_world(f.common,f.military,f.mc,f.access,forged,f.catalog).ok,"cold fabricated damage has no registered hull fact");forged=f.state;forged.fleets[0].request_key=StableId(129,'x');check(!validate_naval_world(f.common,f.military,f.mc,f.access,forged,f.catalog).ok,"history-only oversized idempotency key rejects without cached result");auto after=take(render_boundary_json(encode_common_state(f.common.state())));auto replay=take(apply_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",form));check(replay.receipt_id==result.receipt_id&&after==take(render_boundary_json(encode_common_state(f.common.state()))),"same key returns exact original receipt and no new IDs");auto conflict=form;conflict.formation.assignments[0].extra_inventory_ids.clear();check(!preview_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",conflict).ok,"same key changed intent rejects");conflict=form;conflict.request_key="embark-another";check(!preview_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",conflict).ok,"new key cannot occupy already bound ships again");
 auto published_common=f.common;auto published_naval=f.state;auto candidate=f.common;auto candidate_naval=f.state;auto failed=apply_naval_command(candidate,f.military,f.mc,f.access,candidate_naval,f.catalog,"captain1",NavalDisband{"leave-one",result.fleet_id});check(!failed.ok&&take(render_boundary_json(encode_common_state(published_common.state())))==after&&take(render_boundary_json(naval_asset_codec::encode(published_naval)))==take(render_boundary_json(naval_asset_codec::encode(f.state))),"failed foreign-command whole candidate leaves published pair unchanged");
 f.common.state().actors.find("captain0")->location=WildernessLocation{"river","town",{50,50}};check(!preview_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",NavalDisband{"leave-one",result.fleet_id}).ok,"cannot release ship into a false berth from midriver");f.common.state().actors.find("captain0")->location=SettlementLocation{"town","north_dock"};f.state.vessels[0].integrity=0;auto left=take(apply_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",NavalDisband{"leave-one",result.fleet_id}));check(left.kind=="naval_disband"&&f.state.fleets[0].status=="released"&&f.state.vessels[0].fleet_id.empty()&&f.state.vessels[0].integrity==0,"disabled afloat hull may disband at true berth without being repaired");auto released=take(render_boundary_json(encode_common_state(f.common.state())));auto repeated=take(apply_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",NavalDisband{"leave-one",result.fleet_id}));check(repeated.receipt_id==left.receipt_id&&released==take(render_boundary_json(encode_common_state(f.common.state()))),"disband replay leaves original history and resources unchanged");check(f.common.inventory("army_store")->lots[0].quantity==60&&f.common.inventory("hold0")->lots[0].quantity==10,"formation and release never move cargo or change title");
 auto json=naval_asset_codec::encode(f.state);check(naval_asset_codec::decode(json,f.catalog).ok,"released binding and both command keys survive strict cold shape");std::cout<<"NAVAL_COMMAND_CHECKS="<<checks<<" FAILURES=0 SCOPE=TYPED_CANDIDATE\n";return 0;}catch(const std::exception& e){std::cerr<<"NAVAL_COMMAND_FAIL checks="<<checks<<" "<<e.what()<<'\n';return 1;}}
